package client

import (
    "context"
    "net/http"
    "time"
    "go.opentelemetry.io/otel"
    "go.opentelemetry.io/otel/propagation"
)

type ResilientServiceClient struct {
    httpClient *http.Client
    serviceName string
}

func (c *ResilientServiceClient) DoRequest(ctx context.Context, targetURL string, timeoutBudget time.Duration) (*http.Response, error) {
    reqCtx, cancel := context.WithTimeout(ctx, timeoutBudget)
    defer cancel()

    req, err := http.NewRequestWithContext(reqCtx, http.MethodGet, targetURL, nil)
    if err != nil {
        return nil, err
    }

    // 1. Inject W3C Distributed Trace Context
    otel.GetTextMapPropagator().Inject(reqCtx, propagation.HeaderCarrier(req.Header))

    // 2. Inject Client Identity and Deadline Budget
    req.Header.Set("X-Service-Source", c.serviceName)
    req.Header.Set("X-Client-Timeout-Ms", time.Duration(timeoutBudget).String())

    return c.httpClient.Do(req)
}

