syntax = "proto3";
package orders.v1;

message OrderRequest {
    string order_id = 1;
    string customer_id = 2;
    int64 amount_cents = 3;
}

message OrderResponse {
    string order_id = 1;
    enum Status { PENDING = 0; CONFIRMED = 1; REJECTED = 2; }
    Status status = 2;
}

service OrderService {
    rpc ProcessOrder(OrderRequest) returns (OrderResponse);
}

// Go Client Dial with Round-Robin Load Balancing
func DialOrderService(ctx context.Context, target string) (*grpc.ClientConn, error) {
    return grpc.DialContext(
        ctx,
        target,
        grpc.WithInsecure(),
        grpc.WithDefaultServiceConfig(`{"loadBalancingPolicy":"round_robin"}`),
    )
}

import { PoolClient } from 'pg';

interface OrderPayload {
  orderId: string;
  userId: string;
  amount: number;
}

export async function createOrderAtomic(
  client: PoolClient,
  order: OrderPayload
): Promise<void> {
  try {
    await client.query('BEGIN');

    // 1. Mutate business aggregate table
    await client.query(
      'INSERT INTO orders (id, user_id, amount, status) VALUES ($1, $2, $3, $4)',
      [order.orderId, order.userId, order.amount, 'PENDING']
    );

    // 2. Insert event into outbox table in the SAME transaction
    const eventPayload = {
      eventType: 'OrderCreated',
      aggregateId: order.orderId,
      payload: order,
      occurredAt: new Date().toISOString(),
    };
    await client.query(
      'INSERT INTO outbox_events (aggregate_id, event_type, payload) VALUES ($1, $2, $3)',
      [order.orderId, eventPayload.eventType, JSON.stringify(eventPayload)]
    );

    await client.query('COMMIT');
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  }
}

// Bounded Public API Contract for Fulfillment Service
export interface FulfillmentServiceContract {
  /**
   * Allocates warehouse inventory for a validated order.
   * Idempotent operation: repeated calls with same allocationId return identical results.
   */
  allocateInventory(
    request: AllocateInventoryRequest
  ): Promise<AllocationResult>;

  releaseInventory(
    allocationId: string,
    reason: string
  ): Promise<void>;
}

export interface AllocateInventoryRequest {
  allocationId: string; // Idempotency key from Order Service
  orderId: string;
  items: Array<{
    sku: string;
    quantity: number;
  }>;
}

export interface AllocationResult {
  success: boolean;
  reservedAt: string;
  assignedWarehouseId: string;
}

